import copy
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st

from intervals import merge_intervals


def reference(intervals):
    for s, e in intervals:
        if s > e:
            raise ValueError
    if not intervals:
        return []
    ordered = sorted(intervals, key=lambda x: (x[0], x[1]))
    out = [ordered[0]]
    for s, e in ordered[1:]:
        ls, le = out[-1]
        if s <= le:
            if e > le:
                out[-1] = (ls, e)
        else:
            out.append((s, e))
    return [tuple(x) for x in out]


def coverage(intervals):
    s = set()
    for a, b in intervals:
        s.update(range(a, b + 1))
    return s


# ---- concrete examples from spec ----
def test_example_1():
    assert merge_intervals([(1, 3), (2, 6), (8, 10), (15, 18)]) == [(1, 6), (8, 10), (15, 18)]

def test_example_2_touch():
    assert merge_intervals([(1, 3), (3, 5)]) == [(1, 5)]

def test_example_3_adjacent():
    assert merge_intervals([(1, 3), (4, 5)]) == [(1, 3), (4, 5)]

def test_example_4_unsorted():
    assert merge_intervals([(5, 7), (1, 2)]) == [(1, 2), (5, 7)]

def test_example_5_empty():
    assert merge_intervals([]) == []

def test_example_6_invalid():
    with pytest.raises(ValueError):
        merge_intervals([(3, 1)])


# ---- small explicit behavior ----
def test_touch_single_point_chain():
    assert merge_intervals([(1, 2), (2, 2), (2, 3)]) == [(1, 3)]

def test_adjacent_single_points_stay_separate():
    assert merge_intervals([(0, 0), (1, 1)]) == [(0, 0), (1, 1)]

def test_adjacent_multi_stay_separate():
    assert merge_intervals([(0, 1), (2, 3)]) == [(0, 1), (2, 3)]

def test_contained_absorbed():
    assert merge_intervals([(1, 10), (2, 3), (4, 5)]) == [(1, 10)]

def test_transitive_chain():
    assert merge_intervals([(1, 2), (2, 3), (3, 4), (5, 6)]) == [(1, 4), (5, 6)]

def test_duplicates():
    assert merge_intervals([(1, 3), (1, 3), (1, 3)]) == [(1, 3)]

def test_single_point_valid():
    assert merge_intervals([(2, 2)]) == [(2, 2)]

def test_negative_intervals():
    assert merge_intervals([(-5, -3), (-3, -1)]) == [(-5, -1)]
    assert merge_intervals([(-5, -4), (-3, -1)]) == [(-5, -4), (-3, -1)]

def test_invalid_among_valid():
    with pytest.raises(ValueError):
        merge_intervals([(1, 2), (5, 4), (1, 1)])

def test_input_not_mutated():
    data = [(5, 7), (1, 3), (2, 4)]
    snapshot = copy.deepcopy(data)
    merge_intervals(data)
    assert data == snapshot

def test_returns_new_list_of_tuples():
    data = [(1, 3), (2, 4)]
    out = merge_intervals(data)
    assert out == [(1, 4)]
    assert isinstance(out, list)
    for x in out:
        assert isinstance(x, tuple)
    # mutating output must not affect input
    out.append((99, 100))
    assert data == [(1, 3), (2, 4)]

def test_sorted_and_strictly_disjoint_small():
    out = merge_intervals([(5, 7), (1, 2), (3, 4)])
    assert out == [(1, 2), (3, 4), (5, 7)]
    for i in range(1, len(out)):
        assert out[i][0] > out[i - 1][1]


# ---- the large-input defect: adjacent must NOT merge ----
def test_large_singletons_stay_separate():
    n = 2000
    data = [(i, i) for i in range(n)]
    assert merge_intervals(data) == data

def test_large_adjacent_pairs_stay_separate():
    n = 1500
    data = [(2 * i, 2 * i + 1) for i in range(n)]
    assert merge_intervals(data) == data

def test_large_touching_chain_collapses():
    n = 2000
    data = [(i, i + 1) for i in range(n)]
    # each touches next (share point), transitive => one
    assert merge_intervals(data) == [(0, n)]

def test_chunk_boundary_1024_vs_1025():
    base = [(i, i) for i in range(1024)]
    assert merge_intervals(base) == base
    extended = [(i, i) for i in range(1025)]
    assert merge_intervals(extended) == extended

def test_large_mixed_reference():
    # adjacent blocks separated by a gap of 2 must stay separate even at scale
    data = [(10 * i, 10 * i + 5) for i in range(1200)]
    assert merge_intervals(data) == sorted(data)

def test_large_overlapping_reference():
    data = [(i, i + 5) for i in range(2000)]
    assert merge_intervals(data) == [(0, 2004)]


# ---- property-based ----
small_intervals = st.tuples(
    st.integers(min_value=-10, max_value=10),
    st.integers(min_value=-10, max_value=10),
).map(lambda p: (min(p[0], p[1]), max(p[0], p[1])) if st else (p[0], p[1]))
# simpler: generate valid intervals directly
valid_interval = st.builds(
    lambda a, l: (a, a + l),
    st.integers(min_value=-20, max_value=20),
    st.integers(min_value=0, max_value=10),
)

@given(st.lists(valid_interval, min_size=0, max_size=50))
def test_property_matches_reference(intervals):
    assert merge_intervals(intervals) == reference(intervals)

@given(st.lists(valid_interval, min_size=1025, max_size=1300))
def test_property_large_matches_reference(intervals):
    assert merge_intervals(intervals) == reference(intervals)

@given(st.lists(valid_interval, min_size=0, max_size=30))
def test_property_sorted_disjoint(intervals):
    out = merge_intervals(intervals)
    for i in range(1, len(out)):
        assert out[i][0] > out[i - 1][0]
        assert out[i][0] > out[i - 1][1]

@given(st.lists(valid_interval, min_size=0, max_size=30))
def test_property_coverage_preserved(intervals):
    out = merge_intervals(intervals)
    assert coverage(out) == coverage(intervals)

@given(st.lists(valid_interval, min_size=1025, max_size=1200))
def test_property_large_coverage_and_disjoint(intervals):
    out = merge_intervals(intervals)
    assert coverage(out) == coverage(intervals)
    for i in range(1, len(out)):
        assert out[i][0] > out[i - 1][1]

@given(st.lists(valid_interval, min_size=0, max_size=20))
def test_property_idempotent(intervals):
    once = merge_intervals(intervals)
    assert merge_intervals(once) == once
    assert merge_intervals(list(reversed(once))) == once

@given(st.lists(valid_interval, min_size=0, max_size=20))
def test_property_order_insensitive(intervals):
    assert merge_intervals(intervals) == merge_intervals(list(reversed(intervals)))

@given(st.lists(st.tuples(st.integers(-5, 5), st.integers(-5, 5)), min_size=1, max_size=20))
def test_property_invalid_raises(intervals):
    assume(any(s > e for s, e in intervals))
    with pytest.raises(ValueError):
        merge_intervals(intervals)
